using System.Security.Claims; using LostFound.Infrastructure.Persistence; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.SignalR; using Microsoft.EntityFrameworkCore;
namespace LostFound.Api.Hubs;
[Authorize] public sealed class CommunicationHub(LostFoundDbContext db):Hub{public async Task JoinConversation(Guid conversationId){var uid=Guid.Parse(Context.User!.FindFirstValue(ClaimTypes.NameIdentifier)!);if(!await db.ConversationParticipants.AnyAsync(x=>x.ConversationId==conversationId&&x.UserId==uid))throw new HubException("Forbidden");await Groups.AddToGroupAsync(Context.ConnectionId,$"conversation:{conversationId}");}public override async Task OnConnectedAsync(){var uid=Context.User!.FindFirstValue(ClaimTypes.NameIdentifier)!;await Groups.AddToGroupAsync(Context.ConnectionId,$"user:{uid}");await base.OnConnectedAsync();}}
